/**
 * Game content for the GitHub Pages edition, loaded from static JSON files
 * generated by scripts/build-pages-content.ts. Only the hosting browser
 * loads it; other players receive just what the game engines show them.
 */
import { GAMES, categoryList, type GameId } from '../../shared/games.ts';
import { KIND_FOR_GAME } from '../../server/games/kinds.ts';
import type { ContentItem, ContentKind } from '../../server/games/types.ts';
import { asset } from '../lib/mode.ts';

interface BaseContent {
  categories: { slug: string; name: string; emoji: string }[];
  items: ContentItem[];
}
interface PictureContent {
  items: ContentItem[];
  images: Record<string, string>;
}

let basePromise: Promise<BaseContent> | null = null;
let picturePromise: Promise<PictureContent> | null = null;
let wordImagePromise: Promise<{ images: Record<string, string> }> | null = null;

async function getJson<T>(file: string): Promise<T> {
  const res = await fetch(asset(`content/${file}`), { cache: 'force-cache' });
  if (!res.ok) throw new Error(`content ${file}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

export function loadBase(): Promise<BaseContent> {
  basePromise ??= getJson<BaseContent>('content.json').catch((e) => {
    basePromise = null;
    throw e;
  });
  return basePromise;
}
function loadPictures(): Promise<PictureContent> {
  picturePromise ??= getJson<PictureContent>('pictures.json').catch((e) => {
    picturePromise = null;
    throw e;
  });
  return picturePromise;
}

function loadWordImages() {
  wordImagePromise ??= getJson<{ images: Record<string, string> }>('word-images.json').catch((e) => {
    wordImagePromise = null;
    throw e;
  });
  return wordImagePromise;
}

/** image id → data: URL, filled when picture pairs are picked */
export const imageUrls = new Map<string, string>();

function svgDataUrl(svg: string): string {
  const bytes = new TextEncoder().encode(svg);
  let bin = '';
  for (let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  return `data:image/svg+xml;base64,${btoa(bin)}`;
}

const PHOTO_PREFIX = 'photo-';

/**
 * Real photos are static .webp files next to the content (same origin for every player), so the
 * engine hands each player just the URL of their own photo — nothing to send over the peer link,
 * and it still works after the host refreshes.
 */
export function imageUrl(id: string): string {
  if (id.startsWith('tmdb:')) {
    // TMDB poster, straight from TMDB's image CDN (no key needed for images)
    const path = id.slice(5);
    return /^\/[A-Za-z0-9_-]{5,64}\.(jpg|jpeg|png|webp)$/.test(path) ? `https://image.tmdb.org/t/p/w500${path}` : '';
  }
  if (id.startsWith(PHOTO_PREFIX)) {
    const key = id.slice(PHOTO_PREFIX.length);
    return /^[a-z0-9-]{1,80}$/.test(key) ? asset(`content/photos/${key}.webp`) : '';
  }
  return imageUrls.get(id) ?? '';
}

/** After the host refreshes, reload the illustrated pictures a restored game still refers to. */
export async function primeImages(state: string) {
  const ids = new Set(state.match(/"(?:img-\d+-[ab]|wimg-\d+)"/g)?.map((m) => m.slice(1, -1)) ?? []);
  const missing = [...ids].filter((id) => !imageUrls.has(id));
  if (!missing.length) return;
  const pics = missing.some((id) => id.startsWith('img-')) ? (await loadPictures().catch(() => null))?.images ?? {} : {};
  const words = missing.some((id) => id.startsWith('wimg-')) ? (await loadWordImages().catch(() => null))?.images ?? {} : {};
  for (const id of missing) {
    const svg = pics[id] ?? words[id];
    if (svg) imageUrls.set(id, svgDataUrl(svg));
  }
}

function shuffle<T>(a: T[]): T[] {
  const r = a.slice();
  for (let i = r.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [r[i], r[j]] = [r[j], r[i]];
  }
  return r;
}

/**
 * What each player has seen, kept in the hosting browser: { userId: { contentId: seconds } }.
 * Content ids of the Pages edition are stable hashes, so this survives new content being added.
 */
const SEEN_KEY = 'khabsa:seen:v1';
const SEEN_MAX_AGE = 365 * 24 * 3600;
const SEEN_MAX_PER_USER = 6000;
type SeenMap = Record<string, Record<string, number>>;

function loadSeen(): SeenMap {
  try {
    const v = JSON.parse(localStorage.getItem(SEEN_KEY) ?? '{}') as unknown;
    return v && typeof v === 'object' && !Array.isArray(v) ? (v as SeenMap) : {};
  } catch {
    return {};
  }
}

function saveSeen(map: SeenMap) {
  try {
    localStorage.setItem(SEEN_KEY, JSON.stringify(map));
  } catch {
    // storage full or blocked: keep only the newest half of every player's history and try once more
    for (const u of Object.keys(map))
      map[u] = Object.fromEntries(
        Object.entries(map[u])
          .sort((a, b) => b[1] - a[1])
          .slice(0, SEEN_MAX_PER_USER / 2),
      );
    try {
      localStorage.setItem(SEEN_KEY, JSON.stringify(map));
    } catch {
      /* history is a nice-to-have */
    }
  }
}

/** Implements the part of ContentRepo that RoomManager uses. */
export class BrowserContent {
  async categoryNames(): Promise<Record<string, string>> {
    const b = await loadBase();
    return Object.fromEntries(b.categories.map((c) => [c.slug, c.name]));
  }

  /** Remembers that these players saw these items, so their next games pick other content first. */
  async markSeen(players: string[], contentIds: string[]): Promise<void> {
    if (!players.length || !contentIds.length) return;
    const map = loadSeen();
    const now = Math.floor(Date.now() / 1000);
    for (const u of new Set(players)) {
      const mine = (map[u] ??= {});
      for (const id of contentIds) mine[id] = now;
      let entries = Object.entries(mine).filter(([, t]) => typeof t === 'number' && now - t < SEEN_MAX_AGE);
      if (entries.length > SEEN_MAX_PER_USER) entries = entries.sort((a, b) => b[1] - a[1]).slice(0, SEEN_MAX_PER_USER);
      map[u] = Object.fromEntries(entries);
    }
    saveSeen(map);
  }

  /**
   * Random selection for a game. Order of preference: items none of `players` has seen (random), then the ones
   * they saw longest ago; ids in `exclude` (used in this room lately) come last. Content only repeats once all of it was played.
   */
  async pick(opts: { kind: ContentKind; count: number; category?: string; difficulty?: string; exclude?: string[]; players?: string[] }): Promise<ContentItem[]> {
    const isPicture = opts.kind === 'picture-pair';
    const all = isPicture ? (await loadPictures()).items : (await loadBase()).items.filter((i) => i.kind === opts.kind);
    const cats = categoryList(opts.category);
    let pool = cats.length ? all.filter((i) => cats.includes(i.category)) : all;
    if (opts.difficulty && opts.difficulty !== 'mixed') pool = pool.filter((i) => i.difficulty === opts.difficulty);
    const count = Math.max(1, Math.min(500, opts.count));
    const excluded = new Set(opts.exclude ?? []);
    const seenMap = opts.players?.length ? loadSeen() : {};
    const histories = (opts.players ?? []).map((u) => seenMap[u]).filter(Boolean);
    const lastSeen = (id: string) => histories.reduce((m, h) => Math.max(m, h[id] ?? 0), 0);
    // shuffled first, then a stable sort: unseen (0) first, then oldest seen; room-recent last
    const ordered = (list: ContentItem[]) =>
      shuffle(list)
        .map((i) => ({ i, x: excluded.has(i.id) ? 1 : 0, t: lastSeen(i.id) }))
        .sort((a, b) => a.x - b.x || a.t - b.t)
        .map((e) => e.i);
    let picked: typeof pool;
    if (cats.length > 1) {
      // an equal share from every chosen category, then mixed up
      const share = Math.ceil(count / cats.length);
      const parts = cats.map((c) => ordered(pool.filter((i) => i.category === c)).slice(0, share));
      picked = [];
      for (let i = 0; picked.length < count && parts.some((p) => i < p.length); i++) for (const p of parts) if (i < p.length && picked.length < count) picked.push(p[i]);
      if (picked.length < count) for (const i of ordered(pool)) if (picked.length < count && !picked.includes(i)) picked.push(i);
      picked = shuffle(picked);
    } else {
      picked = ordered(pool).slice(0, count);
    }
    if (isPicture) {
      const { images } = await loadPictures();
      for (const p of picked) {
        const d = p.data as { a: string; b: string };
        for (const id of [d.a, d.b]) if (!imageUrls.has(id) && images[id]) imageUrls.set(id, svgDataUrl(images[id]));
      }
    }
    const wordImageIds = picked.map((i) => (i.data as { image?: string }).image).filter((x): x is string => !!x && !imageUrls.has(x));
    if (wordImageIds.length) {
      // pictures are optional: the game still works if this file can't load
      const { images } = await loadWordImages().catch(() => ({ images: {} as Record<string, string> }));
      for (const id of wordImageIds) if (images[id]) imageUrls.set(id, svgDataUrl(images[id]));
    }
    return picked.map((i) => ({ ...i, data: { ...i.data } }));
  }
}

/** Categories with item counts for the lobby's category picker. */
export async function categoriesFor(gameId: string | null) {
  const b = await loadBase();
  if (!gameId || !(gameId in GAMES)) return b.categories;
  const kind = KIND_FOR_GAME[gameId as GameId];
  const items = kind === 'picture-pair' ? (await loadPictures()).items : b.items.filter((i) => i.kind === kind);
  const counts = new Map<string, number>();
  for (const i of items) counts.set(i.category, (counts.get(i.category) ?? 0) + 1);
  return b.categories.filter((c) => counts.has(c.slug)).map((c) => ({ ...c, items: counts.get(c.slug) }));
}
